/**
 * @name SQL injection from request data
 * @description User-controlled request data flowing into SQL execution
 * @kind problem
 * @problem.severity error
 * @id py/dj-sqli
 * @tags security
 *        external/cwe/cwe-089
 */
import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module SqlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node n) {
    n instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node n) {
    n = any(SqlExecution s).getSql()
  }
}

module SqlInjectionFlow = TaintTracking::Global<SqlInjectionConfig>;

from DataFlow::Node src, DataFlow::Node sink
where SqlInjectionFlow::flow(src, sink)
select sink, "SQL injection: user input from $@ reaches SQL execution.", src, "request data"

/**
 * @name Path traversal in file read sinks
 * @description Potentially unsafe file path construction / open calls in request handling code
 * @kind problem
 * @problem.severity warning
 * @id py/dj-path-traversal
