/**
 * @name SSRF from request data
 * @description Remote request data flowing into an HTTP client / urlopen
 * @kind problem
 * @problem.severity warning
 * @id py/dj-ssrf
 * @tags security
 *        external/cwe/cwe-918
 */
import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SsrfCfg implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node n) {
    n instanceof RemoteFlowSource
  }
  predicate isSink(DataFlow::Node n) {
    exists(DataFlow::CallCfgNode c |
      (
        c = API::moduleImport("urllib.request").getMember(["urlopen", "urlretrieve"]).getACall() or
        c = API::moduleImport("urllib").getMember("urlopen").getACall() or
        c = API::moduleImport("requests").getMember(["get", "post", "put", "head", "request"]).getACall()
      ) and
      n = c.getArg(0)
    )
  }
}

module SsrfFlow = TaintTracking::Global<SsrfCfg>;

from DataFlow::Node src, DataFlow::Node sink
where SsrfFlow::flow(src, sink)
select sink, "SSRF: request data from $@ reaches an HTTP client URL.", src, "request data"
